typedef float time_value_t;
typedef unsigned int big_int;

class stringx;
class string_buf
{
protected:
    friend class stringx;
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
};

class stringx
{
protected:
    char *chars;
    string_buf *my_buf;
public:
    inline int size() const
    {
        return my_buf->char_length;
    }
};

extern int nglGetScreenWidth();
extern int nglGetScreenHeight();

template <class T> void adjustSizes(T &x, T &y)
{
    x = (T) (x*(nglGetScreenWidth()/640.f));
    y = (T) (y*(nglGetScreenHeight()/480.f));
}

class StringList
{
public:
    enum { MAX_STRING_SIZE = 150 };
    static float SPEED_FALL;
    static float SPEED_DRIFT;

    stringx data;
    float x;
    float y;
    float fall_speed[MAX_STRING_SIZE];
    float drift_speed[MAX_STRING_SIZE];
    int drift_max[MAX_STRING_SIZE];
    float delta_x[MAX_STRING_SIZE];
    float delta_y[MAX_STRING_SIZE];

    void Update(time_value_t time_inc);
};

void StringList::Update(const time_value_t time_inc)
{
    float driftSpeed = SPEED_DRIFT;
    float fallSpeed = SPEED_FALL;

    adjustSizes(driftSpeed, fallSpeed);

    for (int i = 0; i < data.size(); i++)
    {
        delta_x[i] += drift_speed[i]*driftSpeed*time_inc;
        if (delta_x[i] < -drift_max[i] && drift_speed[i] < 0.0f)
        {
            drift_speed[i] = -drift_speed[i];
            delta_x[i] = -drift_max[i];
        }
        else if (delta_x[i] > drift_max[i] && drift_speed[i] > 0.0f)
        {
            drift_speed[i] = -drift_speed[i];
            delta_x[i] = drift_max[i];
        }

        delta_y[i] += fall_speed[i]*fallSpeed*time_inc;
    }
}
